import os, re, sys
from pathlib import Path

def parse_frontmatter(text):
    if not text.startswith('---'):
        return None
    parts = text.split('---',2)
    if len(parts) < 3:
        return None
    fm = parts[1]
    data = {}
    for line in fm.splitlines():
        if not line.strip() or line.strip().startswith('#'):
            continue
        if ':' not in line:
            continue
        k,v = line.split(':',1)
        data[k.strip()] = v.strip()
    return data

def check(root):
    issues=[]
    for skill_dir in Path(root).iterdir():
        if not skill_dir.is_dir():
            continue
        skill_md = skill_dir / 'SKILL.md'
        if not skill_md.exists():
            issues.append((skill_dir.name, 'missing SKILL.md'))
            continue
        text = skill_md.read_text(encoding='utf-8')
        data = parse_frontmatter(text) or {}
        name = data.get('name')
        if name and name != skill_dir.name:
            issues.append((skill_dir.name, f'name mismatch: {name}'))
    return issues

roots=[('codex', 'apm_source/codex_cli/.skills'), ('opencode', 'apm_source/cli_ide/apm_opencode_pack/skill')]
for label, root in roots:
    issues=check(root)
    if issues:
        print(label, 'issues:')
        for s in issues:
            print(' ', s)
    else:
        print(label, 'ok')
PY"}

